-- Preenche somente lacunas do catálogo: ultimates já configuradas manualmente são preservadas.
UPDATE "characters" AS character
SET "ultimate" = catalog."ultimate"
FROM (
  VALUES
    ('Naruto', 'Naruto Uzumaki', $ultimate${"id":"naruto_rasengan","name":"Rasengan","description":"Uma esfera de chakra concentrado que perfura a defesa inimiga.","chargeRequired":100,"chargeOnBasic":24,"chargeOnDamageTaken":10,"chargeOnCritical":8,"type":"DAMAGE","targetType":"single_enemy","multiplier":3,"statusEffects":[{"type":"defense_down","chance":70,"duration":2,"value":20}],"conditionalRules":[{"condition":"HP abaixo de 50%","effect":"multiplicador aumenta em 0,3"}]}$ultimate$::jsonb),
    ('Naruto', 'Sakura Haruno', $ultimate${"id":"sakura_hundred_healings","name":"Força de Cem Selos","description":"Libera chakra acumulado para restaurar e proteger toda a equipe.","chargeRequired":110,"chargeOnBasic":18,"chargeOnDamageTaken":16,"chargeOnCritical":0,"type":"HEAL","targetType":"aoe_ally","multiplier":2.2,"statusEffects":[{"type":"shield","chance":100,"duration":2,"value":180},{"type":"defense_up","chance":100,"duration":2,"value":20}],"conditionalRules":[{"condition":"Aliado abaixo de 35% de HP","effect":"prioriza a cura em área"}]}$ultimate$::jsonb),
    ('One Piece', 'Monkey D. Luffy', $ultimate${"id":"luffy_red_roc","name":"Gear Third: Gomu Gomu no Red Roc","description":"Um soco gigantesco em chamas que atinge todos os inimigos.","chargeRequired":105,"chargeOnBasic":20,"chargeOnDamageTaken":18,"chargeOnCritical":4,"type":"AOE","targetType":"aoe_enemy","multiplier":2.05,"statusEffects":[{"type":"burn","chance":75,"duration":2,"value":55}],"conditionalRules":[{"condition":"Após usar","effect":"velocidade reduzida por 1 turno"}]}$ultimate$::jsonb),
    ('Bleach', 'Ichigo Kurosaki', $ultimate${"id":"ichigo_getsuga","name":"Getsuga Tensho","description":"Uma lâmina de energia espiritual que corta um único alvo.","chargeRequired":95,"chargeOnBasic":26,"chargeOnDamageTaken":8,"chargeOnCritical":10,"type":"EXECUTE","targetType":"single_enemy","multiplier":3.25,"statusEffects":[{"type":"bleed","chance":70,"duration":2,"value":65}],"conditionalRules":[{"condition":"Alvo abaixo de 25% de HP","effect":"dano de execução é priorizado"}]}$ultimate$::jsonb),
    ('Dragon Ball', 'Goku', $ultimate${"id":"goku_kamehameha","name":"Kamehameha","description":"Uma rajada colossal de ki que explode em toda a linha inimiga.","chargeRequired":140,"chargeOnBasic":14,"chargeOnDamageTaken":8,"chargeOnCritical":5,"type":"AOE","targetType":"aoe_enemy","multiplier":3.1,"statusEffects":[{"type":"defense_down","chance":60,"duration":2,"value":25}],"conditionalRules":[{"condition":"Carga alta","effect":"carrega lentamente em troca de dano explosivo em área"}]}$ultimate$::jsonb),
    ('Naruto', 'Sasuke Uchiha', $ultimate${"id":"sasuke_kirin","name":"Kirin / Chidori","description":"Canaliza relâmpagos para paralisar e fulminar o inimigo.","chargeRequired":105,"chargeOnBasic":22,"chargeOnDamageTaken":10,"chargeOnCritical":8,"type":"STUN","targetType":"single_enemy","multiplier":2.7,"statusEffects":[{"type":"shock","chance":100,"duration":2,"value":60},{"type":"stun","chance":70,"duration":1,"value":0}],"conditionalRules":[{"condition":"Alvo está em choque","effect":"atordoamento tem prioridade"}]}$ultimate$::jsonb),
    ('One Piece', 'Roronoa Zoro', $ultimate${"id":"zoro_ichidai_sanzen","name":"Santoryu: Ichidai Sanzen Daisen Sekai","description":"Um corte de três espadas que atravessa a guarda do alvo.","chargeRequired":115,"chargeOnBasic":21,"chargeOnDamageTaken":12,"chargeOnCritical":7,"type":"DAMAGE","targetType":"single_enemy","multiplier":3.45,"statusEffects":[{"type":"bleed","chance":100,"duration":3,"value":70}],"conditionalRules":[{"condition":"Após usar","effect":"velocidade reduzida por 1 turno pela recuperação"}]}$ultimate$::jsonb),
    ('Demon Slayer', 'Tanjiro Kamado', $ultimate${"id":"tanjiro_hinokami_kagura","name":"Hinokami Kagura","description":"Uma dança solar que incendeia todos os inimigos atingidos.","chargeRequired":100,"chargeOnBasic":23,"chargeOnDamageTaken":11,"chargeOnCritical":7,"type":"AOE","targetType":"aoe_enemy","multiplier":2.15,"statusEffects":[{"type":"burn","chance":100,"duration":3,"value":65}],"conditionalRules":[{"condition":"Após usar","effect":"recebe dano de recuo de 5% do HP máximo"}]}$ultimate$::jsonb),
    ('Jujutsu Kaisen', 'Yuji Itadori', $ultimate${"id":"yuji_black_flash","name":"Black Flash","description":"Um golpe de energia amaldiçoada sincronizado no instante perfeito.","chargeRequired":85,"chargeOnBasic":28,"chargeOnDamageTaken":12,"chargeOnCritical":18,"type":"DAMAGE","targetType":"single_enemy","multiplier":2.8,"statusEffects":[{"type":"attack_down","chance":65,"duration":2,"value":15}],"conditionalRules":[{"condition":"Acerto crítico","effect":"recebe carga extra para encadear o próximo Black Flash"}]}$ultimate$::jsonb)
) AS catalog("anime", "name", "ultimate")
WHERE character."anime" = catalog."anime"
  AND character."name" = catalog."name"
  AND character."ultimate" IS NULL;
--> statement-breakpoint

-- Verificação administrativa: qualquer linha retornada ainda usaria a ultimate genérica por role.
SELECT "id", "anime", "name"
FROM "characters"
WHERE "ultimate" IS NULL
ORDER BY "anime", "name";
